    <template #icon>
      <div class="flex items-center">
        <div 
          class="tooltip tooltip-right" 
          :data-tip="profile.name || profile.username" 
          v-for="profile in messageProfiles.slice(0, 1)" 
          :key="profile.name"
        >
          <ProfileAvatar :profile="profile" width="6" />
        </div>
      </div>
    </template>

    <!-- Smart title based on message type -->
    <template #title>
      <div class="flex items-center gap-2">
        <span class="text-xs font-semibold text-base-content/80">
          {{ displayMessage.is_answer ? '✓ Answer' : displayMessage.user }}
        </span>
        <span class="text-xs text-base-content/50">{{ formatDate(displayMessage.updated_at) }}</span>
      </div>
    </template>

    <!-- Summary: First 80 chars of content + badges -->
    <template #summary>
      <span v-if="messageContent" class="text-xs text-base-content/50 line-clamp-1">
        {{ messageContent.substring(0, 80).replace(/#+\s?/g, '') }}{{ messageContent.length > 80 ? '…' : '' }}
      </span>
      <div class="badge badge-xs gap-1" :class="displayMessage.is_answer ? 'badge-success' : 'badge-outline'" v-if="displayMessage.is_answer">
        <i class="fa-solid fa-star"></i>
      </div>
      <div class="badge badge-xs badge-info badge-outline gap-1" v-if="isTopic">
        <ChatIcon mode="topic" />
      </div>
      <span v-if="cancellationTime" class="badge badge-xs badge-error gap-1">
        <i class="fa-solid fa-ban"></i>
      </span>
    </template>

    <!-- Compact actions -->
    <template #actions>
      <div class="flex gap-1">
        <!-- Context buttons -->
        <button 
          class="btn btn-xs btn-ghost gap-1 tooltip tooltip-bottom opacity-0 group-hover:opacity-100" 
          data-tip="Thread" 
          @click.stop="$emit('thread', message)"
        >
          <i class="fa-solid fa-comment-dots text-xs"></i>
        </button>
        <button 
          class="btn btn-xs btn-ghost gap-1 tooltip tooltip-bottom opacity-0 group-hover:opacity-100" 
          data-tip="Copy" 
          @click.stop="copyMessageToClipboard"
        >
          <i class="fa-solid fa-copy text-xs"></i>
        </button>

        <!-- More actions dropdown -->
        <div class="dropdown dropdown-end">
          <button tabindex="0" class="btn btn-xs btn-ghost opacity-0 group-hover:opacity-100">
            <i class="fa-solid fa-ellipsis-vertical text-xs"></i>
          </button>
          <ul tabindex="0" class="dropdown-content menu rounded-lg shadow w-40 p-1 bg-base-100 z-50 border border-base-200">
            <li><a @click.stop="$emit('answer', message)" v-if="!displayMessage.is_answer" class="text-success"><i class="fa-solid fa-star"></i> Best answer</a></li>
            <li><a @click.stop="togglePRView" v-if="hasPRViewBlocks"><i class="fa-solid fa-code-branch"></i> Code review</a></li>
            <li><a @click.stop="toggleShowDiff" v-if="displayMessage.diffMessage"><i class="fa-regular fa-file-lines"></i> View diff</a></li>
            <li><a @click.stop="toggleSrcView" v-if="isDone"><i class="fa-solid fa-code"></i> Raw text</a></li>
            <li><a @click.stop="runAgents"><i class="fa-solid fa-people-group"></i> Run agents</a></li>
            <li><a @click.stop="$emit('hide', message)"><i class="fa-solid fa-box-archive"></i> {{ displayMessage.hide ? 'Unarchive' : 'Archive' }}</a></li>
            <li><a @click.stop="confirmRemove" class="text-error"><i class="fa-solid fa-trash-can"></i> Delete</a></li>
          </ul>
        </div>
      </div>
    </template>

    <!-- Content body — expanded on click -->
    <div class="p-2 flex flex-col gap-2 border-t border-base-300/30">
      <!-- Loading progress -->
      <progress class="progress progress-sm w-full" v-if="!isDone"></progress>

      <!-- Error display -->
      <div class="alert alert-error text-xs" v-if="displayMessage.error">
        {{ displayMessage.error }}
      </div>

      <!-- Thinking section -->
      <div 
        v-if="thinkText" 
        class="alert alert-info items-start text-xs cursor-pointer"
        @click="displayMessage.full_think = !displayMessage.full_think"
      >
        <i class="fa-solid fa-brain"></i>
        <span class="line-clamp-2">{{ thinkText }}</span>
      </div>

      <!-- Selection menu -->
      <ChatEntrySelectionMenu
        v-if="showSelectionMenu"
        :selectedText="selectedText"
        :chatProject="chatProject"
        @copy="onSelectionCopy"
        @create-subtask="onSelectionCreateSubtask"
        @search-files="onSelectionSearchFiles"
        @close="onCloseSelectionMenu"
      />

      <!-- Skeleton loader -->
      <div v-if="!displayMessage.content && !displayMessage.think" class="space-y-1">
        <div class="skeleton h-8 w-full"></div>
        <div class="skeleton h-8 w-5/6"></div>
      </div>

      <!-- TOC for documents -->
      <DocumentSummary
        v-if="isDone && messageContent && !showPRView && !srcView && !showDiff"
        :content="messageContent"
        :minHeadings="4"
        :documentId="documentId"
        :scrollContainer="$refs.contentArea"
        class="text-xs"
      />

      <!-- Message content -->
      <div 
        ref="contentArea"
        @copy.stop="onMessageCopy"
        @mouseup="onContentMouseUp"
        class="max-w-full text-sm"
      >
        <pre v-if="srcView" class="text-xs bg-base-200 p-2 rounded overflow-auto max-h-96">{{ displayMessage.content }}</pre>

        <Document 
          v-if="!showDiff && !srcView && !showPRView && !code_patches && !isWord"
          :content="messageContent"
          :files="chatFiles"
          :project="chatProject"
          :chat="chat"
          :loading="!message.done"
          :documentId="documentId"
          :message="message"
          @generate-code="onGenerateCode"
          @reload-file="$emit('reload-file', { file: $event, message })"
          @open-file="$emit('open-file', $event)"
          @save-file="$emit('save-file', $event)"
          @add-file="$emit('add-file', $event)"
          @sub-task="$emit('sub-task', $event)"
          @copy-chapter="onCopyChapter"
          @create-task="onCreateTask"
          :mentionList="mentionList"
        >
          <template #chapter-actions="{ chapter, fullContent }">
            <button class="btn btn-xs btn-ghost gap-1" @click="copyChapterMarkdown(chapter, fullContent)">
              <i class="fa-solid fa-copy"></i>
            </button>
            <button class="btn btn-xs btn-ghost gap-1" @click="createTaskFromChapter(chapter, fullContent)">
              <i class="fa-solid fa-plus"></i>
            </button>
          </template>
        </Document>

        <CodeDiff
          v-if="showDiff && !showPRView"
          :new-string="displayMessage.diffMessage.content"
          :old-string="messageContent"
          theme="dark"
        />

        <!-- Code patches -->
        <div v-if="code_patches && !showPRView" class="space-y-2">
          <div 
            v-for="patch in code_patches" 
            :key="patch.file_path"
            class="border border-base-300 rounded p-2"
          >
            <div class="text-xs font-bold text-primary mb-1">
              {{ patch.file_path.replace($project.abs_project_path, '') }}
            </div>
            <Markdown :text="'```diff\n' + patch.patch + '\n```'"></Markdown>
            <div class="flex justify-end mt-2">
              <button 
                class="btn btn-xs btn-warning" 
                :disabled="patch.working" 
                @click="applyPatch(patch)"
              >
                <span class="loading loading-spinner" v-if="patch.working"></span>
                Apply
              </button>
            </div>
          </div>
        </div>

        <!-- PR View -->
        <MessagePRView
          v-if="showPRView && !srcView && !showDiff"
          :codeBlocks="prViewCodeBlocks"
          :chat="chat"
          :message="message"
          :activeBranch="activeBranch"
          @save-file="$emit('save-file', $event)"
          @add-file="$emit('add-file', $event)"
          @open-file="$emit('open-file', $event)"
          @sub-task="$emit('sub-task', $event)"
        />

        <!-- Images -->
        <div v-if="images && !showPRView && images?.length" class="mt-2">
          <div class="carousel gap-2">
            <div 
              class="carousel-item cursor-pointer"
              v-for="image in images" 
              :key="image.src" 
              @click="$emit('image', image)"
            >
              <div 
                class="bg-cover bg-center border rounded w-16 h-16"
                :style="`background-image: url(${image.src})`"
              ></div>
            </div>
          </div>
        </div>

        <!-- Linked files -->
        <div v-if="displayMessage.files?.length && !showPRView" class="mt-2 text-xs">
          <p class="font-semibold mb-1">Files</p>
          <div class="space-y-1">
            <div 
              v-for="file in displayMessage.files" 
              :key="file"
              class="flex gap-2 items-center"
            >
              <i class="fa-solid fa-file text-info"></i>
              <a class="hover:underline cursor-pointer truncate" @click="openFile(file)">{{ file.split('/').reverse()[0] }}</a>
              <i class="fa-regular fa-circle-xmark cursor-pointer hover:text-error" @click.stop="$emit('remove-file', file)"></i>
            </div>
          </div>
        </div>
      </div>
    </div>
  </Collapsible>
</template>

<script>
export default {
  props: ['chat', 'message', 'mentionList', 'menu-less', 'usersList'],
  emits: [
    'generate-code', 'reload-file', 'open-file', 'save-file',
    'add-file', 'sub-task', 'thread', 'hide',
    'remove', 'answer', 'enhance', 'copy', 'add-file-to-chat',
    'remove-file', 'image', 'run-agents', 'edit-message', 'search-files'
  ],
  data() {
    return {
      srcView: false,
      isRemove: false,
      improvementData: null,
      showDiff: false,
      showPRView: false,
      documentId: 'doc-' + Math.random().toString(36).slice(2, 8),
      activeBranch: null,
      branchLoading: false,
      showSelectionMenu: false,
      selectedText: '',
      selectionPosition: { top: 0, left: 0 },
      collapsed: false
    }
  },
  created() {
    this.loadThreadChat()
    this.loadActiveBranch()
  },
  computed: {
    isDone() {
      return this.displayMessage.done
    },
    isWord() {
      return this.chat?.mode === 'word'
    },
    isTopic() {
      return this.chat?.mode === 'topic'
    },
    isSlackStyle() {
      return this.chat?.mode === 'topic'
    },
    isCollapsed() {
      if (this.collapsed !== undefined) return this.collapsed
      if (this.displayMessage.hide) return true
      if (this.displayMessage.is_answer) return true
      return false
    },
    isMyMessage() {
      return this.displayMessage.user === this.$user.username
    },
    isChannelMessage() {
      return this.chat.mode === 'channel'
    },
    canEditMessage() {
      return !this.isChannelMessage ||
        this.isMyMessage ||
        this.message.role === 'assistant'
    },
    thinkText() {
      return null
    },
    displayMessage() {
      const message = this.threadChat?.messages
          .filter(m => !m.hide)
          .reverse()[0] || this.message
      return message
    },
    messageProfiles() {
      let profiles = this.$projects.profiles
        ?.filter(p => this.displayMessage.profiles?.includes(p.name)) || []
      const user = this.$project.users
        .find(({ username }) => username === this.displayMessage.user)
      return [user, ...profiles].filter(u => !!u)
    },
    images() {
      return this.message?.images?.map(i => {
        try {
          return JSON.parse(i)
        } catch {
          return { src: i }
        }
      })
    },
    messageContent() {
      return this.displayMessage.content
    },
    code_changes() {
      return this.improvementData?.code_changes
    },
    code_patches() {
      return this.improvementData?.code_patches
    },
    timeTaken() {
      if (!this.displayMessage.meta_data) return null
      let timeTaken = '--'
      if (this.displayMessage.meta_data?.time_taken) {
        const seconds = Math.floor(this.displayMessage.meta_data.time_taken)
        const baseMoment = moment({ h: 0, m: 0, s: 0, ms: 0 })
        timeTaken = baseMoment.add(seconds, 'seconds').format('mm:ss')
      } else if (this.displayMessage.meta_data?.start_time) {
        timeTaken = moment(this.displayMessage.meta_data?.start_time).fromNow()
      }
      return timeTaken
    },
    chatProject() {
      if (this.chat.project_id) {
        return this.$projects.allProjects.find(p => p.project_id === this.chat.project_id)
      }
      return this.$project
    },
    chatFiles() {
      return this.chat.file_list
    },
    threadChat() {
      return this.$projects.allChats.find(c => c.message_id === this.message.doc_id)
    },
    cancellationTokenId() {
      return this.displayMessage.meta_data?.cancellation_token_id
    },
    cancellationTime() {
      return this.displayMessage.meta_data?.cancelled_at
    },
    hasPRViewBlocks() {
      return this.$service.chat.hasCodeBlocksWithFilePaths(this.displayMessage)
    },
    prViewCodeBlocks() {
      return this.$service.chat.extractCodeBlocksFromMessage(this.displayMessage)
    }
  },
  watch: {
    message() {
      this.loadThreadChat()
    },
    'message.content': function() {
      this.extractImprovementData()
    }
  },
  methods: {
    formatDate(date) {
      return moment(date).format('DD/MMM HH:mm')
    },
    extractImprovementData() {
      this.improvementData = null
      if (this.displayMessage.content?.startsWith('```json')) {
        try {
          const lines = this.displayMessage.content.split('\n')
          const jsBlock = lines.slice(1, lines.length - 1).join('\n')
          this.improvementData = JSON.parse(jsBlock)
        } catch (ex) {
          console.error('Failed to parse improvement data', ex)
        }
      }
    },
    copyTextToClipboard(text) {
      this.$ui.copyTextToClipboard(text)
    },
    onMessageCopy(ev) {
      const text = window.getSelection().toString()
      if (text) {
        this.copyTextToClipboard(text)
        ev.preventDefault()
      }
    },
    getSelectionPosition() {
      const selection = window.getSelection()
      if (selection.rangeCount === 0) return { top: 0, left: 0 }
      const range = selection.getRangeAt(0)
      const rect = range.getBoundingClientRect()
      return {
        top: Math.max(10, rect.top + window.scrollY - 60),
        left: rect.left
      }
    },
    onContentMouseUp() {
      function getSelectedHTML() {
        const selection = window.getSelection()
        if (selection.rangeCount > 0) {
          const range = selection.getRangeAt(0)
          const clonedContent = range.cloneContents()
          const div = document.createElement('div')
          div.appendChild(clonedContent)
          return div.innerHTML
        }
        return ""
      }

      const selectedText = getSelectedHTML()
      this.showSelectionMenu = selectedText.length > 0
      if (this.showSelectionMenu) {
        this.selectedText = selectedText
      }
    },
    onSelectionCopy(text) {
      this.copyTextToClipboard(text)
    },
    onSelectionCreateSubtask(content) {
      this.$emit('sub-task', { content })
    },
    onSelectionSearchFiles({ query }) {
      this.$emit('search-files', { query, fromSelection: true })
    },
    onCloseSelectionMenu() {
      this.showSelectionMenu = false
    },
    toggleSrcView() {
      this.srcView = !this.srcView
      if (this.srcView) {
        this.showDiff = false
        this.showPRView = false
      }
    },
    toggleShowDiff() {
      this.showDiff = !this.showDiff
      if (this.showDiff) {
        this.srcView = false
        this.showPRView = false
      }
    },
    togglePRView() {
      this.showPRView = !this.showPRView
      if (this.showPRView) {
        this.srcView = false
        this.showDiff = false
        this.loadActiveBranch()
      }
    },
    onRemove() {
      if (this.isRemove) {
        this.$emit('remove')
      } else {
        this.isRemove = true
      }
    },
    confirmRemove() {
      this.isRemove = true
      this.$emit('remove')
    },
    copyMessageToClipboard() {
      this.copyTextToClipboard(this.displayMessage.content)
    },
    async applyPatch(patch) {
      patch.working = true
      try {
        const code_changes = this.code_changes.filter(cc => cc.file_path === patch.file_path)
        await this.$projects.codeImprovePatch({
          chat: this.chat,
          code_generator: { code_changes, code_patches: [patch] }
        })
        patch.res = { info: 'Patch sent' }
      } catch {
        patch.res = { error: 'Error' }
      }
      delete patch.working
    },
    onGenerateCode(codeBlockInfo) {
      this.$emit('generate-code', codeBlockInfo)
    },
    openFile(file) {
      this.$emit('preview-file', file)
    },
    openThread() {
      this.$chats.setActiveChat(this.threadChat)
    },
    loadThreadChat() {
      if (this.threadChat) {
        this.$chats.reloadChat(this.threadChat)
      }
    },
    runAgents() {
      this.$emit('run-agents', this.message)
    },
    async cancelMessage() {
      const tokenId = this.cancellationTokenId
      if (!tokenId) return
      try {
        await this.$storex.api.chats.cancelMessage(tokenId)
      } catch (ex) {
        console.error('Failed to cancel message', ex)
      }
    },
    async loadActiveBranch() {
      if (this.branchLoading) return
      this.branchLoading = true
      try {
        const repoInfo = await this.chatProject.$api.repo.info()
        this.activeBranch = repoInfo?.active_branch
      } catch (ex) {
        console.error('Failed to load active branch', ex)
        this.activeBranch = null
      } finally {
        this.branchLoading = false
      }
    },
    copyChapterMarkdown(chapter, fullContent) {
      this.copyTextToClipboard(fullContent)
    },
    createTaskFromChapter(chapter, fullContent) {
      this.$emit('sub-task', { content: fullContent, title: chapter.title })
    },
    onCopyChapter(chapterData) {
      this.copyTextToClipboard(chapterData.content)
    },
    onCreateTask(taskData) {
      this.$emit('sub-task', { content: taskData.content, title: taskData.title })
    }
  },
  mounted() {
    this.extractImprovementData()
  }
}
</script>
```

---

## Summary of Changes

| Aspect | V1: Compact | V2: Rich Header | V3: Progressive |
|--------|---|---|---|
| **Collapsed Avatar Size** | 5 (20px) | 6 (24px) | 6 (24px) |
| **Header Padding** | Default | sm-md | xs |
| **Action Button Visibility** | Hover (xs) | Always visible | Hover (xs) |
| **Default State** | Manual toggle | Manual toggle | Closed (answers), Open (regular) |
| **Content Preview** | None | None | First 80 chars |
| **Use When** | Scanning long threads | Detailed review mode | Mixed density chats |

---

## Anti-Patterns to Avoid

1. ❌ **Removing aria-labels or keyboard navigation** — Collapsible must remain accessible. Ensure `tabindex="0"` and ARIA attributes are preserved.

2. ❌ **Mixing uncontrolled and controlled state** — Always use `:modelValue` + `@update:modelValue` to sync collapse state. Avoid race conditions between local `collapsed` and parent state.

3. ❌ **Action buttons without hover/focus indication** — Opacity-0 hidden buttons must have `:focus-visible` styling. Use Tailwind's `@lg:opacity-0 group-hover:opacity-100 focus-visible:opacity-100`.

